async function toggleTranslation(message: Message) {
    if (translations[message.id]) {
      setTranslations((current) => {
        const next = { ...current };
        delete next[message.id];
        return next;
      });
      setTranslationProviders((current) => {
        const next = { ...current };
        delete next[message.id];
        return next;
      });
      return;
    }
    await performTranslation(message, targetLanguage);
  }

